// DPoP keys protected by this device's security chip: the Secure Enclave on a
// Mac, the TPM on Windows and Linux. The DPoP key itself is a software key,
// and the login saves it only sealed by a key that never leaves the chip, so
// a copy of the login can't be unsealed, or sign, on any other device.
//
// Unsealing asks for nothing (no password, Touch ID, or PIN), so it doesn't
// protect against code running as the user on this device: that code can
// have the chip unseal the key, the same way the CLI does, and then use it
// anywhere. Sealing protects a copied login, not a compromised device.
//
// Once unsealed, a key is kept in this process's memory for
// `DPOP_KEY_CACHE_TTL_MS`, so a command uses the chip once, not for every
// request (a deploy signs one for every file it uploads). Nothing unsealed
// outlives the command.

import {
  createECDH,
  createPrivateKey,
  generateKeyPairSync,
  type KeyObject,
  randomUUID,
  sign,
} from 'node:crypto';
import {
  createSecureEnclaveKey,
  unsealWithSecureEnclaveKey,
} from './secure-enclave';
import { createTpmKey, deleteTpmKey, unsealWithTpmKey } from './tpm';
import { hasLinuxTpm, sealWithLinuxTpm, unsealWithLinuxTpm } from './linux-tpm';
import { hasKoffi } from './koffi';

export { TpmAccessError } from './linux-tpm';
export { SecureEnclaveLockedError } from './secure-enclave';

/**
 * How long an unsealed DPoP key is kept in memory, so the chip isn't used
 * for every request. Fixed from when the key was unsealed, not extended by
 * use, which only matters to long-running commands.
 */
export const DPOP_KEY_CACHE_TTL_MS = 30 * 60 * 1000;

/**
 * A DPoP key's private half (`d`), `sealed` by a key in this device's chip:
 * a Secure Enclave key, in the wrapped form only this Mac's Secure Enclave
 * can use, the name of a key in this PC's TPM, or, on Linux, the public area
 * of a TPM sealed object whose private area is `sealed`.
 */
export type HardwareKeyHandle = (
  | { secureEnclave: string }
  | { tpm: string }
  | { tpmPublic: string }
) & {
  sealed: string;
};

export type HardwareKey = HardwareKeyHandle & { x: string; y: string };

/**
 * Whether this device may have a security chip `createHardwareKey` can use:
 * every Mac and Windows PC where koffi is installed (the native CLI ships it,
 * the npm CLI doesn't), and a Linux machine whose kernel exposes a TPM.
 */
export function hasSecurityChip(): boolean {
  return (
    ((process.platform === 'darwin' || process.platform === 'win32') &&
      hasKoffi()) ||
    (process.platform === 'linux' && hasLinuxTpm())
  );
}

/**
 * Create a P-256 DPoP key sealed by this device's Secure Enclave (macOS) or
 * TPM (Windows, Linux). Throws when there's no such chip, or it can't be
 * used.
 */
export function createHardwareKey(): HardwareKey {
  if (
    process.platform !== 'darwin' &&
    process.platform !== 'win32' &&
    process.platform !== 'linux'
  ) {
    throw new Error(
      `There's no supported security chip on ${process.platform}.`
    );
  }
  const { privateKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' });
  const { x, y, d } = privateKey.export({ format: 'jwk' });
  if (!x || !y || !d) {
    throw new Error('Failed to export the DPoP key.');
  }
  const secret = Buffer.from(d, 'base64url');
  try {
    if (process.platform === 'darwin') {
      const { wrapped, sealed } = createSecureEnclaveKey(secret);
      return {
        secureEnclave: wrapped.toString('base64url'),
        sealed: sealed.toString('base64url'),
        x,
        y,
      };
    }
    if (process.platform === 'linux') {
      const sealed = sealWithLinuxTpm(secret);
      return {
        tpmPublic: sealed.public.toString('base64url'),
        sealed: sealed.private.toString('base64url'),
        x,
        y,
      };
    }
    const name = `vercel-cli-dpop-${randomUUID()}`;
    const sealed = createTpmKey(name, secret);
    return { tpm: name, sealed: sealed.toString('base64url'), x, y };
  } finally {
    secret.fill(0);
  }
}

/**
 * Sign `data` with ECDSA P-256 and SHA-256 using a hardware-sealed key,
 * unsealing it with the chip unless it was unsealed in the last
 * `DPOP_KEY_CACHE_TTL_MS`. Returns the signature as `r || s` (IEEE P1363), as
 * JWS uses for ES256.
 */
export function signWithHardwareKey(
  key: HardwareKey,
  data: Uint8Array
): Buffer {
  return sign('sha256', data, {
    key: unsealed(key),
    dsaEncoding: 'ieee-p1363',
  });
}

/**
 * Delete a hardware key once nothing uses it, forgetting it if it's
 * unsealed. A Secure Enclave key and a Linux sealed object are only what's
 * in the login, so only a Windows TPM key is deleted from the chip.
 */
export function deleteHardwareKey(key: HardwareKeyHandle): void {
  forget(cacheId(key));
  if ('tpm' in key) {
    deleteTpmKey(key.tpm);
  }
}

// Keys this process unsealed, by `cacheId`.
const unsealedKeys = new Map<
  string,
  { key: KeyObject; timer: ReturnType<typeof setTimeout> }
>();

function cacheId(key: HardwareKeyHandle): string {
  if ('secureEnclave' in key) {
    return `secureEnclave:${key.secureEnclave}:${key.sealed}`;
  }
  if ('tpmPublic' in key) {
    return `tpmPublic:${key.tpmPublic}:${key.sealed}`;
  }
  return `tpm:${key.tpm}:${key.sealed}`;
}

function unsealed(key: HardwareKey): KeyObject {
  const id = cacheId(key);
  const cached = unsealedKeys.get(id);
  if (cached) {
    return cached.key;
  }
  const keyObject = unseal(key);
  // Dropped when its time is up, even if the process is idle, so nothing
  // holds it longer. The timer doesn't keep the process running.
  const timer = setTimeout(() => forget(id), DPOP_KEY_CACHE_TTL_MS);
  timer.unref?.();
  unsealedKeys.set(id, { key: keyObject, timer });
  return keyObject;
}

function forget(id: string): void {
  const cached = unsealedKeys.get(id);
  if (cached) {
    clearTimeout(cached.timer);
    unsealedKeys.delete(id);
  }
}

function unseal(key: HardwareKey): KeyObject {
  const sealed = Buffer.from(key.sealed, 'base64url');
  let secret: Buffer;
  if ('secureEnclave' in key) {
    secret = unsealWithSecureEnclaveKey(
      Buffer.from(key.secureEnclave, 'base64url'),
      sealed
    );
  } else if ('tpmPublic' in key) {
    secret = unsealWithLinuxTpm({
      public: Buffer.from(key.tpmPublic, 'base64url'),
      private: sealed,
    });
  } else {
    secret = unsealWithTpmKey(key.tpm, sealed);
  }
  try {
    // Not every Node version checks that `d` is the private half of `x` and
    // `y` on import, so derive its public key and compare.
    const ecdh = createECDH('prime256v1');
    ecdh.setPrivateKey(
      new Uint8Array(secret.buffer, secret.byteOffset, secret.length)
    );
    const point = ecdh.getPublicKey();
    if (
      point.subarray(1, 33).toString('base64url') !== key.x ||
      point.subarray(33).toString('base64url') !== key.y
    ) {
      throw new Error("The unsealed DPoP key doesn't match its public key.");
    }
    return createPrivateKey({
      key: {
        kty: 'EC',
        crv: 'P-256',
        x: key.x,
        y: key.y,
        d: secret.toString('base64url'),
      },
      format: 'jwk',
    });
  } finally {
    secret.fill(0);
  }
}
